<template>
  <div class="mx-auto grid max-w-4xl overflow-hidden rounded-[28px] bg-white shadow-xl shadow-blue-950/10 lg:grid-cols-[.85fr_1.15fr]">
    <div class="gradient-brand hidden p-9 text-white lg:block"><span class="grid size-12 place-items-center rounded-2xl bg-teal-300 text-2xl font-black text-blue-950">ی</span><h2 class="mt-16 text-3xl font-black leading-[1.5]">یک همراه<br>ساده برای<br>هر روز.</h2><p class="mt-5 text-sm leading-7 text-blue-100/70">حساب رایگان خودت را بساز و از یک کار کوچک شروع کن.</p></div>
    <div class="p-6 sm:p-10"><div class="mb-8 lg:hidden"><span class="grid size-11 place-items-center rounded-2xl bg-blue-950 text-xl font-black text-white">ی</span></div><p class="text-sm font-bold text-teal-700">شروع ساده</p><h1 class="mt-2 text-3xl font-black text-slate-900">ساخت حساب رایگان</h1><p class="mt-2 text-sm text-slate-500">فقط چند اطلاعات ساده لازم است.</p><form class="mt-8 space-y-5" @submit.prevent="submit"><label class="block text-sm font-bold text-slate-700">نام<input v-model="form.name" type="text" autocomplete="name" required placeholder="نام شما" class="focus-ring mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4"></label><label class="block text-sm font-bold text-slate-700">ایمیل<input v-model="form.email" type="email" autocomplete="email" required placeholder="you@example.com" class="focus-ring mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-left font-latin placeholder:text-slate-400" dir="ltr"></label><label class="block text-sm font-bold text-slate-700">رمز عبور<input v-model="form.password" type="password" autocomplete="new-password" minlength="8" required placeholder="حداقل ۸ کاراکتر" class="focus-ring mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-left font-latin placeholder:text-slate-400" dir="ltr"><span class="mt-1 block text-xs font-normal text-slate-400">رمزت را جایی امن نگه دار.</span></label><p v-if="error" class="rounded-xl bg-red-50 p-3 text-sm text-red-700" role="alert">{{ error }}</p><button class="focus-ring w-full rounded-xl bg-blue-950 px-4 py-3 font-bold text-white transition hover:bg-blue-900 disabled:cursor-wait disabled:opacity-60" :disabled="loading">{{ loading ? 'در حال ساخت حساب…' : 'ساخت حساب رایگان' }}</button></form><p class="mt-7 text-center text-sm text-slate-500">قبلاً ثبت‌نام کرده‌اید؟ <NuxtLink to="/login" class="font-bold text-teal-700 hover:text-teal-800">وارد شوید</NuxtLink></p><NuxtLink to="/support" class="mt-4 block text-center text-xs text-slate-400 hover:text-teal-700">حمایت از سازنده یار تو</NuxtLink></div>
  </div>
</template>

<script setup lang="ts">
const { fetch: fetchSession } = useUserSession()
const form = reactive({ name: '', email: '', password: '' }); const error = ref(''); const loading = ref(false)
async function submit() { loading.value = true; error.value = ''; try { await $fetch('/api/auth/register', { method: 'POST', body: form }); await fetchSession(); await navigateTo('/dashboard') } catch (e: any) { error.value = e?.data?.message || e?.statusMessage || 'ثبت‌نام انجام نشد. دوباره تلاش کنید.' } finally { loading.value = false } }
</script>
